-- ============================================================
-- 吳玉柱退休財務儀表板 — 完整建置腳本（最終版）
-- 來源：吳玉柱勞保資料.xlsx  |  產生：2026-05-22
-- 步驟：phpMyAdmin → fan_members → SQL → 貼上 → 執行
-- ============================================================

SET NAMES utf8mb4;

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 第一部分：建立資料表
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

-- ① 勞保投保主紀錄表
CREATE TABLE IF NOT EXISTS `labor_insurance_records` (
  `id`              INT           AUTO_INCREMENT PRIMARY KEY,
  `member_id`       INT           NOT NULL,
  `seq`             TINYINT       NOT NULL COMMENT '序號',
  `ins_num`         VARCHAR(14)   NOT NULL COMMENT '保險證號',
  `company`         VARCHAR(60)   NOT NULL COMMENT '投保單位名稱',
  `labor_salary`    INT           NOT NULL DEFAULT 0 COMMENT '勞就保投保薪資',
  `disaster_salary` INT           NOT NULL DEFAULT 0 COMMENT '災保投保薪資',
  `start_date`      DATE          NOT NULL COMMENT '生效日期',
  `end_date`        DATE          NULL     COMMENT '退保日期（NULL=在保中）',
  `remark`          VARCHAR(100)  NOT NULL DEFAULT '' COMMENT '備註',
  `created_at`      TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_member` (`member_id`),
  INDEX `idx_salary` (`labor_salary` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='勞工保險投保紀錄';

-- ② 月份展開分析表（60月稽核用）
CREATE TABLE IF NOT EXISTS `labor_insurance_monthly_analysis` (
  `id`            INT         AUTO_INCREMENT PRIMARY KEY,
  `member_id`     INT         NOT NULL,
  `year_month`    CHAR(7)     NOT NULL COMMENT 'yyyy-mm',
  `labor_salary`  INT         NOT NULL COMMENT '當月投保薪資',
  `company`       VARCHAR(60) NOT NULL COMMENT '投保單位',
  `record_seq`    TINYINT     NOT NULL COMMENT '來源主紀錄序號',
  `salary_rank`   SMALLINT    NULL     COMMENT '薪資由高至低排名',
  `in_top60`      TINYINT(1)  NOT NULL DEFAULT 0 COMMENT '是否列入前60月（1=是）',
  INDEX `idx_mm`   (`member_id`, `year_month`),
  INDEX `idx_rank` (`member_id`, `in_top60`, `salary_rank`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='勞保月份展開（60月平均薪資稽核）';

-- ③ 退休規劃參數表
CREATE TABLE IF NOT EXISTS `retirement_profiles` (
  `id`                           INT           AUTO_INCREMENT PRIMARY KEY,
  `member_id`                    INT           NOT NULL UNIQUE,
  `birth_year`                   SMALLINT      NOT NULL DEFAULT 1962,
  `birth_month`                  TINYINT       NOT NULL DEFAULT 1,
  `target_retire_age`            TINYINT       NOT NULL DEFAULT 65,
  `labor_insurance_years`        DECIMAL(5,2)  NOT NULL DEFAULT 0,
  `highest_60_months_avg`        INT           NOT NULL DEFAULT 0,
  `current_labor_pension_fund`   DECIMAL(14,0) NOT NULL DEFAULT 0,
  `monthly_contribution_wage`    INT           NOT NULL DEFAULT 0,
  `employer_pension_rate`        DECIMAL(5,4)  NOT NULL DEFAULT 0.0600,
  `self_pension_rate`            DECIMAL(5,4)  NOT NULL DEFAULT 0.0000,
  `expected_return_rate`         DECIMAL(5,4)  NOT NULL DEFAULT 0.0400,
  `securities_value`             DECIMAL(14,0) NOT NULL DEFAULT 0,
  `securities_return_rate`       DECIMAL(5,4)  NOT NULL DEFAULT 0.0700,
  `savings_insurance_value`      DECIMAL(14,0) NOT NULL DEFAULT 0,
  `other_assets_value`           DECIMAL(14,0) NOT NULL DEFAULT 0,
  `updated_at`                   TIMESTAMP     DEFAULT CURRENT_TIMESTAMP
                                               ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='退休規劃個人參數';

-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
-- 第二部分：清除舊資料（冪等保護）
-- ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

DELETE FROM `labor_insurance_records`          WHERE `member_id` = (SELECT MIN(id) FROM members WHERE role='admin');
DELETE FROM `labor_insurance_monthly_analysis` WHERE `member_id` = (SELECT MIN(id) FROM members WHERE role='admin');
DELETE FROM `retirement_profiles`              WHERE `member_id` = (SELECT MIN(id) FROM members WHERE role='admin');

