SELECT '月份展開記錄'      AS 資料表, COUNT(*) AS 筆數 FROM `labor_insurance_monthly_analysis`
UNION ALL
SELECT '列入60月計算'      AS 資料表, COUNT(*) AS 筆數 FROM `labor_insurance_monthly_analysis` WHERE `in_top60`=1
UNION ALL
SELECT '退休參數'          AS 資料表, COUNT(*) AS 筆數 FROM `retirement_profiles`;

-- 正確結果應為：59 / 5438 / 60 / 1
